SELECT p.gender, p.anchor_year, p.anchor_year_group, COUNT(DISTINCT i.stay_id) AS icu_stays, COUNT(DISTINCT pr.procedure_id) AS avg_procedures, MIN(pr.procedure_id) AS min_procedures, MAX(pr.procedure_id) AS max_procedures, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT i.stay_id), 0) AS mortality_rate, AVG(i.los) AS avg_los, SUM(CASE WHEN r.readmission_date IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT i.stay_id), 0) AS readmission_rate FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN procedures_icd pr ON i.stay_id = pr.subject_id AND i.hadm_id = pr.hadm_id LEFT JOIN (SELECT subject_id, hadm_id, readmission_date FROM icustays WHERE length_of_stay <= 30) r ON p.subject_id = r.subject_id AND i.hadm_id = r.hadm_id WHERE p.gender = 'M' AND p.anchor_year BETWEEN 66 AND 76 AND p.hospital_expire_flag = 'Y' GROUP BY p.gender, p.anchor_year, p.anchor_year_group ORDER BY p.gender, p.anchor_year, p.anchor_year_group NULLS LAST;